(()=>{const reduce=matchMedia('(prefers-reduced-motion: reduce)');const button=document.querySelector('#motion');let disabled=reduce.matches;const letters=[...document.querySelectorAll('.builder>span')];const assembly=document.querySelector('.assembly');const assemblyPin=assembly.querySelector('.assembly-pin');const assemblyScenes=[...assembly.querySelectorAll('.assembly-scene')];const assemblySteps=[...assembly.querySelectorAll('.assembly-step')];const star=document.querySelector('.kitchen-star');const system=document.querySelector('.system-visual');const progress=document.querySelector('.progress');let pending=false;const clamp=(v,a=0,b=1)=>Math.min(b,Math.max(a,v));function paintAssembly(){const r=assembly.getBoundingClientRect();const p=clamp(-r.top/Math.max(1,r.height-assemblyPin.getBoundingClientRect().height));const stage=Math.min(2,Math.floor(p*3));const local=p*3-stage;const ease=v=>v*v*(3-2*v);const phase=(a,b)=>ease(clamp((local-a)/(b-a)));assembly.dataset.scene=['code','build','cook'][stage];assemblyScenes.forEach((scene,i)=>{scene.classList.toggle('is-current',i===stage);scene.style.setProperty('--scene-opacity',(stage===0?1:clamp(local/.06))*(stage===2?1:clamp((1-local)/.06)));assemblySteps[i].style.setProperty('--step-progress',clamp(p*3-i))});const scene=assemblyScenes[stage];const raw=stage===0?phase(.1,.7):phase(.08,.35);const reveal=stage===0?phase(.18,.38):stage===1?phase(.67,.77):phase(.86,.96);const values={'--gather':raw,'--spread':1-raw,'--piece-scale':1-.25*raw,'--input-opacity':1-phase(stage===0?.65:.22,stage===0?.8:.43),'--output-opacity':reveal,'--output-scale':.95+.05*reveal,'--origin-opacity':.65*(1-.65*phase(.2,.35)*(1-phase(.74,.9)))};if(stage===0){Object.assign(values,{'--wire-one':phase(0,.16),'--wire-two':phase(.04,.2),'--wire-three':phase(.08,.24),'--wire-main':phase(.18,.34),'--code-one':phase(.1,.43),'--code-two':phase(.24,.57),'--code-three':phase(.37,.7),'--code-heading':phase(.26,.45),'--code-bars':phase(.64,.82),'--code-action':phase(.72,.86),'--code-live':phase(.8,.91)})}else if(stage===1){Object.assign(values,{'--carry':phase(.77,.91),'--leg-fit':phase(.16,.42),'--leg-show':phase(.12,.23),'--rail-fit':phase(.32,.57),'--rail-show':phase(.27,.38),'--seat-fit':phase(.51,.73),'--seat-show':phase(.46,.57)})}else{const stir=phase(.38,.71);Object.assign(values,{'--carry':phase(.76,.9),'--bowl-show':phase(.15,.27),'--noodle-drop':phase(.26,.51),'--noodle-show':phase(.23,.34),'--sauce-show':phase(.38,.48)*(1-phase(.67,.78)),'--stir-angle':Math.sin(stir*Math.PI*2)*15+'deg','--stir-x':Math.sin(stir*Math.PI*2)*14+'px','--basil-drop':phase(.65,.84),'--basil-show':phase(.61,.72)})}Object.entries(values).forEach(([key,value])=>scene.style.setProperty(key,value))}function paint(){pending=false;const y=scrollY,h=innerHeight;progress.style.transform=`scaleX(${clamp(y/(document.documentElement.scrollHeight-h))})`;if(disabled)return;paintAssembly();letters.forEach((l,i)=>{const p=clamp(y/h);l.style.transform=`translateY(${p*(i%2?-32:25)}px) rotate(${p*(i-3)*1.5}deg)`});const kr=star.getBoundingClientRect();star.style.transform=`rotate(${(h-kr.top)*.06}deg)`;if(system){const sr=system.getBoundingClientRect();system.style.transform=`rotate(${clamp((sr.top/h)*6,-3,3)}deg)`}}function request(){if(!pending){pending=true;requestAnimationFrame(paint)}}function sync(){document.body.classList.toggle('no-motion',disabled);button.setAttribute('aria-pressed',String(disabled));button.textContent=disabled?'Motion off':'Motion on';document.documentElement.style.scrollBehavior=disabled?'auto':'smooth';request()}button.addEventListener('click',()=>{disabled=!disabled;sync()});reduce.addEventListener('change',e=>{disabled=e.matches;sync()});addEventListener('scroll',request,{passive:true});addEventListener('resize',request);sync()})();
